/**
 * Seat accounting shared by invitations and role changes: only billable roles
 * (`owner`, `admin`, `member`) occupy a seat, so the same count backs both the
 * invite quota and the viewer-to-billable role-change quota.
 */
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import type { OrgId } from "@/types/common";

export async function countSeatsUsed(orgId: OrgId): Promise<number> {
  return (
    (await memberRepo.countBillableActiveMembers(orgId)) +
    (await invitationRepo.countPendingBillableInvitations(orgId))
  );
}

